@page "/settings"
@using sv_e19398e8fd1a4af9b886413884ece9b5.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <h2>Settings</h2>
        <ul>
            <li class="@(ActiveSection == "Profile" ? "active" : "")" @onclick='() => SetSection("Profile")'>
                <span class="nav-icon">👤</span> Profile
            </li>
            <li class="@(ActiveSection == "Notifications" ? "active" : "")" @onclick='() => SetSection("Notifications")'>
                <span class="nav-icon">🔔</span> Notifications
            </li>
            <li class="@(ActiveSection == "Security" ? "active" : "")" @onclick='() => SetSection("Security")'>
                <span class="nav-icon">🔒</span> Security
            </li>
            <li class="@(ActiveSection == "Appearance" ? "active" : "")" @onclick='() => SetSection("Appearance")'>
                <span class="nav-icon">🎨</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (!string.IsNullOrEmpty(ToastMessage))
        {
            <div class="toast @ToastType">
                @ToastMessage
                <button class="toast-close" @onclick="DismissToast">×</button>
            </div>
        }

        @if (ActiveSection == "Profile")
        {
            <section class="settings-section">
                <h3>Profile Settings</h3>
                @if (_profile is not null)
                {
                    <div class="profile-layout">
                        <div class="avatar-area">
                            <img src="@_editProfile.AvatarUrl" alt="Avatar" class="avatar-preview" />
                            <p class="avatar-url">@_editProfile.AvatarUrl</p>
                        </div>
                        <div class="profile-fields">
                            <div class="field-group">
                                <label for="displayName">Display Name</label>
                                <input id="displayName" type="text" @bind="_editProfile.DisplayName" />
                            </div>
                            <div class="field-group">
                                <label for="email">Email</label>
                                <input id="email" type="email" @bind="_editProfile.Email" />
                            </div>
                            <div class="field-group">
                                <label for="bio">Bio</label>
                                <textarea id="bio" rows="4" @bind="_editProfile.Bio"></textarea>
                            </div>
                            <div class="button-group">
                                <button class="btn-primary" @onclick="SaveProfile">Save Changes</button>
                                <button class="btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
                            </div>
                        </div>
                    </div>
                }
            </section>
        }
        else if (ActiveSection == "Notifications")
        {
            <section class="settings-section">
                <h3>Notification Preferences</h3>
                @if (_notificationPrefs is not null)
                {
                    <div class="toggle-group">
                        <label class="toggle-label">
                            <input type="checkbox" @bind="_editEmailNotifications" />
                            <span class="toggle-switch"></span>
                            Email Notifications
                        </label>
                        <label class="toggle-label">
                            <input type="checkbox" @bind="_editPushNotifications" />
                            <span class="toggle-switch"></span>
                            Push Notifications
                        </label>
                        <label class="toggle-label">
                            <input type="checkbox" @bind="_editWeeklyDigest" />
                            <span class="toggle-switch"></span>
                            Weekly Digest
                        </label>
                    </div>

                    <h4>Muted Channels</h4>
                    <div class="channel-list">
                        @foreach (var channel in _allChannels)
                        {
                            <label class="channel-item">
                                <input type="checkbox" checked="@IsChannelMuted(channel)"
                                       @onchange="(e) => ToggleChannelMute(channel, (bool)(e.Value ?? false))" />
                                @channel
                            </label>
                        }
                    </div>

                    <div class="button-group">
                        <button class="btn-primary" @onclick="SaveNotifications">Save Preferences</button>
                    </div>
                }
            </section>
        }
        else if (ActiveSection == "Security")
        {
            <section class="settings-section">
                <h3>Security Settings</h3>
                @if (_security is not null)
                {
                    <div class="expandable-panel">
                        <button class="panel-header" @onclick="TogglePasswordPanel">
                            <span>Change Password</span>
                            <span class="expand-icon">@(_passwordPanelOpen ? "▼" : "▶")</span>
                        </button>
                        @if (_passwordPanelOpen)
                        {
                            <div class="panel-body">
                                <div class="field-group">
                                    <label for="currentPassword">Current Password</label>
                                    <input id="currentPassword" type="password" @bind="_currentPassword" />
                                </div>
                                <div class="field-group">
                                    <label for="newPassword">New Password</label>
                                    <input id="newPassword" type="password" @bind="_newPassword" />
                                </div>
                                <div class="field-group">
                                    <label for="confirmPassword">Confirm Password</label>
                                    <input id="confirmPassword" type="password" @bind="_confirmPassword" />
                                </div>
                                <button class="btn-primary" @onclick="ChangePassword">Update Password</button>
                            </div>
                        }
                    </div>

                    <div class="toggle-group" style="margin-top: 1.5rem;">
                        <label class="toggle-label">
                            <input type="checkbox" @bind="_twoFactorEnabled" />
                            <span class="toggle-switch"></span>
                            Two-Factor Authentication
                            <span class="status-indicator @(_twoFactorEnabled ? "status-on" : "status-off")">
                                @(_twoFactorEnabled ? "Enabled" : "Disabled")
                            </span>
                        </label>
                    </div>

                    @if (_security.LastPasswordChange.HasValue)
                    {
                        <p class="info-text">Last password change: @_security.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                    }

                    <h4>Active Sessions</h4>
                    <div class="sessions-table-wrapper">
                        <table class="sessions-table">
                            <thead>
                                <tr>
                                    <th>Device</th>
                                    <th>Location</th>
                                    <th>Last Active</th>
                                    <th>Action</th>
                                </tr>
                            </thead>
                            <tbody>
                                @foreach (var session in _security.Sessions)
                                {
                                    <tr>
                                        <td>@session.Device</td>
                                        <td>@session.Location</td>
                                        <td>@FormatLastActive(session.LastActive)</td>
                                        <td>
                                            @if (session.Id == _currentSessionId)
                                            {
                                                <span class="current-badge">Current</span>
                                            }
                                            else
                                            {
                                                <button class="btn-danger-sm" @onclick="() => ConfirmRevokeSession(session)">Revoke</button>
                                            }
                                        </td>
                                    </tr>
                                }
                            </tbody>
                        </table>
                    </div>

                    @if (_showRevokeConfirm && _sessionToRevoke is not null)
                    {
                        <div class="modal-overlay" @onclick="CancelRevoke">
                            <div class="modal" @onclick:stopPropagation="true">
                                <h4>Confirm Session Revocation</h4>
                                <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> from <strong>@_sessionToRevoke.Location</strong>?</p>
                                <div class="button-group">
                                    <button class="btn-danger" @onclick="RevokeSession">Revoke Session</button>
                                    <button class="btn-secondary" @onclick="CancelRevoke">Cancel</button>
                                </div>
                            </div>
                        </div>
                    }
                }
            </section>
        }
        else if (ActiveSection == "Appearance")
        {
            <section class="settings-section">
                <h3>Appearance Settings</h3>

                <div class="field-group">
                    <label>Theme</label>
                    <div class="radio-group">
                        <label class="radio-label">
                            <input type="radio" name="theme" value="Light" @onchange='() => _editTheme = "Light"' checked="@(_editTheme == "Light")" /> Light
                        </label>
                        <label class="radio-label">
                            <input type="radio" name="theme" value="Dark" @onchange='() => _editTheme = "Dark"' checked="@(_editTheme == "Dark")" /> Dark
                        </label>
                        <label class="radio-label">
                            <input type="radio" name="theme" value="System" @onchange='() => _editTheme = "System"' checked="@(_editTheme == "System")" /> System
                        </label>
                    </div>
                </div>

                <div class="field-group">
                    <label>Font Size</label>
                    <div class="radio-group">
                        <label class="radio-label">
                            <input type="radio" name="fontSize" value="Small" @onchange='() => _editFontSize = "Small"' checked="@(_editFontSize == "Small")" /> Small
                        </label>
                        <label class="radio-label">
                            <input type="radio" name="fontSize" value="Medium" @onchange='() => _editFontSize = "Medium"' checked="@(_editFontSize == "Medium")" /> Medium
                        </label>
                        <label class="radio-label">
                            <input type="radio" name="fontSize" value="Large" @onchange='() => _editFontSize = "Large"' checked="@(_editFontSize == "Large")" /> Large
                        </label>
                    </div>
                </div>

                <div class="field-group">
                    <label for="language">Language</label>
                    <select id="language" @bind="_editLanguage">
                        <option value="English">English</option>
                        <option value="Spanish">Spanish</option>
                        <option value="French">French</option>
                        <option value="German">German</option>
                        <option value="Japanese">Japanese</option>
                        <option value="Chinese">Chinese</option>
                    </select>
                </div>

                <div class="toggle-group">
                    <label class="toggle-label">
                        <input type="checkbox" @bind="_editCompactMode" />
                        <span class="toggle-switch"></span>
                        Compact Mode
                    </label>
                </div>

                <h4>Live Preview</h4>
                <div class="live-preview @GetPreviewClasses()">
                    <div class="preview-header">Header Area</div>
                    <div class="preview-body">
                        <p>This is a preview of how your content will look with the selected settings.</p>
                        <button class="preview-btn">Sample Button</button>
                    </div>
                    <div class="preview-sidebar">Sidebar</div>
                </div>

                <div class="button-group">
                    <button class="btn-primary" @onclick="SaveAppearance">Save</button>
                </div>
            </section>
        }
    </main>
</div>

@code {
    private string ActiveSection { get; set; } = "Profile";

    // Toast
    private string? ToastMessage { get; set; }
    private string ToastType { get; set; } = "toast-success";

    // Profile
    private UserProfile? _profile;
    private ProfileEdit _editProfile = new();

    // Notifications
    private NotificationPrefs? _notificationPrefs;
    private bool _editEmailNotifications;
    private bool _editPushNotifications;
    private bool _editWeeklyDigest;
    private List<string> _editMutedChannels = new();
    private readonly List<string> _allChannels = new() { "general", "marketing", "announcements", "engineering", "design", "support" };

    // Security
    private SecuritySettings? _security;
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _twoFactorEnabled;
    private bool _showRevokeConfirm;
    private ActiveSession? _sessionToRevoke;
    private readonly string _currentSessionId = "sess-1";

    // Appearance
    private string _editTheme = "Light";
    private string _editFontSize = "Medium";
    private string _editLanguage = "English";
    private bool _editCompactMode;

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettings();
    }

    private async Task LoadAllSettings()
    {
        _profile = await SettingsService.GetProfileAsync();
        _editProfile = new ProfileEdit
        {
            DisplayName = _profile.DisplayName,
            Email = _profile.Email,
            AvatarUrl = _profile.AvatarUrl,
            Bio = _profile.Bio
        };

        _notificationPrefs = await SettingsService.GetNotificationPrefsAsync();
        _editEmailNotifications = _notificationPrefs.EmailNotifications;
        _editPushNotifications = _notificationPrefs.PushNotifications;
        _editWeeklyDigest = _notificationPrefs.WeeklyDigest;
        _editMutedChannels = new List<string>(_notificationPrefs.MutedChannels);

        _security = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = _security.TwoFactorEnabled;

        var appearance = await SettingsService.GetAppearanceAsync();
        _editTheme = appearance.Theme;
        _editFontSize = appearance.FontSize;
        _editLanguage = appearance.Language;
        _editCompactMode = appearance.CompactMode;
    }

    private void SetSection(string section)
    {
        ActiveSection = section;
        DismissToast();
    }

    // Toast helpers
    private void ShowToast(string message, string type = "toast-success")
    {
        ToastMessage = message;
        ToastType = type;
    }

    private void DismissToast() => ToastMessage = null;

    // Profile
    private async Task SaveProfile()
    {
        var updated = new UserProfile(_editProfile.DisplayName, _editProfile.Email, _editProfile.AvatarUrl, _editProfile.Bio);
        await SettingsService.SaveProfileAsync(updated);
        _profile = updated;
        ShowToast("Profile saved successfully!");
    }

    private void DiscardProfileChanges()
    {
        if (_profile is not null)
        {
            _editProfile = new ProfileEdit
            {
                DisplayName = _profile.DisplayName,
                Email = _profile.Email,
                AvatarUrl = _profile.AvatarUrl,
                Bio = _profile.Bio
            };
        }
        ShowToast("Changes discarded.", "toast-info");
    }

    // Notifications
    private bool IsChannelMuted(string channel) => _editMutedChannels.Contains(channel);

    private void ToggleChannelMute(string channel, bool muted)
    {
        if (muted && !_editMutedChannels.Contains(channel))
            _editMutedChannels.Add(channel);
        else if (!muted)
            _editMutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(_editEmailNotifications, _editPushNotifications, _editWeeklyDigest, new List<string>(_editMutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _notificationPrefs = prefs;
        ShowToast("Notification preferences saved!");
    }

    // Security
    private void TogglePasswordPanel() => _passwordPanelOpen = !_passwordPanelOpen;

    private async Task ChangePassword()
    {
        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            ShowToast("Please fill in all password fields.", "toast-error");
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            ShowToast("New passwords do not match.", "toast-error");
            return;
        }
        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _security = await SettingsService.GetSecuritySettingsAsync();
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _passwordPanelOpen = false;
        ShowToast("Password updated successfully!");
    }

    private void ConfirmRevokeSession(ActiveSession session)
    {
        _sessionToRevoke = session;
        _showRevokeConfirm = true;
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
        _showRevokeConfirm = false;
    }

    private async Task RevokeSession()
    {
        if (_sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            _security = await SettingsService.GetSecuritySettingsAsync();
            ShowToast($"Session on {_sessionToRevoke.Device} has been revoked.");
        }
        CancelRevoke();
    }

    private string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
        return $"{(int)diff.TotalDays} days ago";
    }

    // Appearance
    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{_editTheme.ToLower()} preview-font-{_editFontSize.ToLower()}";
        if (_editCompactMode) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_editTheme, _editFontSize, _editLanguage, _editCompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
